class Department {
  + name : string
}

class ResearchGroup {
  + name : string
}

class Researcher {
  + name : string
  + employeeId : int
}

class Project {
  + title : string
  + budget : float
}

class WorkPackage {
  + wpNumber : string
  + description : string
}

Department "1" -- "1..*" ResearchGroup
ResearchGroup "1" -- "1..*" Researcher
ResearchGroup "1" -- "1..*" WorkPackage : leads
WorkPackage "*" -- "1" ResearchGroup : ledBy
WorkPackage "*" -- "1..*" Researcher : assignedTo

@enduml

